mapper.select:
SELECT
,T2.FINPROD_ID FINPROD_ID , T2.FINPROD_TYPE FINPROD_TYPE , T2.FINPROD_TYPE2 FINPROD_TYPE2 , T2.FINPROD_ABBR FINPROD_ABBR , T2.FINPROD_NAME FINPROD_NAME , T2.COUPON_SPECIES , T3.EFF_DATE EFF_DATE , T3.PAY_CYCLE_VAL PAY_CYCLE_VAL , T3.PAY_CYCLE PAY_CYCLE , T3.DAY_TYPE DAY_TYPE , T3.DAY_VALUE DAY_VALUE , T3.END_TDAY_RULE END_TDAY_RULE , T3.PAY_TDAY_RULE PAY_TDAY_RULE , T3.CALC_RULE CALC_RULE , T3.FIRST_PAY_DATE FIRST_PAY_DATE , T3.CASH_UNIT_TYPE CASH_UNIT_TYPE ,T3.REMARK REMARK ,T3.PAY_MONTH FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T3 ON T3.CASH_ID = T1.CASH_ID
AND T3.EFF_DATE = to_date ( #{vdate}, 'yyyy-mm-dd' )
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}

SELECT
,T2.CASH_TYPE_2 FROM FIN_CASH_PLAN T1, FIN_CASH_INFO T2 WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
ORDER BY T1.VDATE ASC

SELECT
, CASE WHEN COUNT(T3.CASH_ID) > 0 THEN 'Y' ELSE 'N' END isPayed ,T1.REMARK FROM FIN_CASH_INFO T2, FIN_CASH_PLAN T1 LEFT JOIN TRD_PRODUCT_DEAL T3 ON T1.CASH_ID = T3.CASH_ID and T3.MDATE = T1.MDATE and T3.TRADE_STATUS = '01' and T3.IS_CANCEL = 'N' WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
GROUP BY T1.CASH_ID, T1.MDATE, T1.CASH_NUM, T1.CASH_TYPE, T1.VDATE_UNADJUST, T1.MDATE_UNADJUST, T1.PAY_DATE_UNADJUST, T1.VDATE, T1.PAY_DATE, T1.TERMDAYS, T1.VDATE_Y, T1.VDATE_TERM, T1.MDATE_TERM, T1.TERMDAYS_TERM, T1.PRIN_AMT, T1.INT_PRIN_AMT, T1.INT_AMT, T1.IS_PAY_INT, T1.CASH_AMT, T1.CASH_BASEAMT, T1.CASH_UNIT_TYPE, T1.CALC_FUNCTION, T1.FREQUENCY, T1.FINPROD_ID, T1.FINPROD_TYPE, T1.FINPROD_TYPE2, T1.BRANCH, T1.PAY_TYPE, T1.RANGE_YIELD, T1.CREATE_USER, T1.CREATE_DEPT, T1.CREATE_TIME, T1.UPDATE_USER, T1.UPDATE_TIME, T1.REMARK

SELECT T4.IS_PAY_INT FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PLAN T4 on T4.CASH_ID =T1.CASH_ID where T2.MDATE=T4.MDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
